const fs = require('node:fs');
const path = require('node:path');
const cp = require('node:child_process');
const crypto = require('node:crypto');
const Module = require('node:module');
const ts = require('typescript');
const esbuild = require('esbuild');
const assert = require('node:assert/strict');
const root = process.cwd();
const parserPath = 'src/lib/import/framing-plan/parse.ts';
const base = '7a12578';
const out = path.join(root, '.cache/phase42-step3');
const sha = b => crypto.createHash('sha256').update(b).digest('hex');
const git = args => cp.execFileSync('git', args, {maxBuffer: 64 * 1024 * 1024});
const save = (name, value) => fs.writeFileSync(path.join(out, name + '.json'), JSON.stringify(value, null, 2) + '\n');
function instrument(source) {
  const ast = ts.createSourceFile(parserPath, source, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS);
  const changes = [];
  let functionName = '';
  const visit = node => {
    const parentName = functionName;
    if (ts.isFunctionDeclaration(node)) functionName = node.name?.text;
    if (ts.isReturnStatement(node) && node.expression && ts.isObjectLiteralExpression(node.expression)) {
      const expr = node.expression;
      const raw = expr.getText(ast);
      if (functionName === 'validateSequence' && expr.properties.some(p => p.name?.getText(ast) === 'spansMm')) {
        const partial = raw.includes('solution.spans\n') || /spansMm:\s*solution\.spans/.test(raw);
        const tokens = partial ? 'solution.spans.slice(first.firstIndex, first.lastIndex)' : raw.includes('selected.solution') ? 'selected.solution.spans' : 'selected.spans';
        changes.push([expr.getStart(ast), expr.end, `__record(${raw}, sequence, ${tokens}, ${partial ? 'first.firstIndex' : '0'}, dimensions)`]);
      }
      if (functionName === 'gridCandidate') changes.push([expr.getStart(ast), expr.end, `__grid(${raw}, sequence)`]);
    }
    ts.forEachChild(node, visit);
    functionName = parentName;
  };
  visit(ast);
  assert.equal(changes.length, 4);
  for (const [start, end, value] of changes.sort((a,b)=>b[0]-a[0])) source = source.slice(0,start)+value+source.slice(end);
  source = source.replace('dimensions.push({', 'dimensions.push({ __raw: normalizedText,');
  return source + `
const __tag = Symbol('step3');
const __grids = new WeakMap();
function __record(result, original, tokens, offset, dimensions) {
  result[__tag] = {original, tokens, offset, dimensions};
  return result;
}
function __grid(result, sequence) { __grids.set(result, sequence); return result; }
export function audit(output) {
  const rows = [];
  const sequences = new Set([...output.grids, ...output.blocks.flatMap(b => [b.xGrid,b.yGrid])].map(g => __grids.get(g)));
  for (const sequence of sequences) {
    const {original,tokens,offset,dimensions} = sequence[__tag];
    const used = new Set(tokens);
    const along = sequence.alongKey;
    const across = along === 'x' ? 'y' : 'x';
    for (let i = 0; i < tokens.length; i++) {
      const midpoint = (sequence.axes[i].positionPt + sequence.axes[i+1].positionPt)/2;
      const bands = [...new Set([...original.axisAcrossOptions[i+offset],...original.axisAcrossOptions[i+offset+1]])];
      const describe = token => ({text:token.__raw,value_mm:token.valueMm,center:{x:token.x,y:token.y},distance_pt:Math.abs(token[along]-midpoint),across_distance_pt:Math.min(...bands.map(b=>Math.abs(token[across]-b)))});
      const competitors = dimensions.filter(d => !used.has(d) && bands.some(b=>Math.abs(d[across]-b)<=DIMENSION_WINDOW_PT)).map(describe).sort((a,b)=>a.distance_pt-b.distance_pt);
      rows.push({direction:sequence.direction,along_key:along,labels:sequence.axes.slice(i,i+2).map(a=>a.label),positions_pt:sequence.axes.slice(i,i+2).map(a=>a.positionPt),midpoint_pt:midpoint,bands_pt:bands,totalConfirmed:sequence.totalConfirmed,accepted:describe(tokens[i]),competitor:competitors[0]??null});
    }
  }
  return rows;
}
`;
}
function compile(source, debug) {
  const code = esbuild.buildSync({stdin:{contents:debug?instrument(source):source,loader:'ts',sourcefile:path.resolve(parserPath),resolveDir:path.dirname(path.resolve(parserPath))},bundle:true,write:false,platform:'node',format:'cjs',logLevel:'silent'}).outputFiles[0].text;
  const evaluated = new Module(path.join(out, 'virtual.cjs'));
  evaluated.filename = path.join(out, 'virtual.cjs');
  evaluated.paths = Module._nodeModulePaths(root);
  evaluated._compile(code, evaluated.filename);
  return evaluated.exports;
}
const currentBytes = fs.readFileSync(parserPath);
const before = git(['show', `${base}:${parserPath}`]).toString('utf8');
const current = currentBytes.toString('utf8');
// runs.ts is the only runtime dependency of this parser; require it unchanged.
assert.equal(git(['diff', base, '--', 'src/lib/import/runs.ts']).length, 0);
const baseline = compile(before, false);
const baselineAudit = compile(before, true);
const now = compile(current, false);
const nowAudit = compile(current, true);
const dir = 'tests/fixtures/section-import/textitems';
const files = fs.readdirSync(dir).filter(f=>f.endsWith('.json')).sort();
assert.equal(files.length, 36);
const pages = files.map(file => {
  const fixture = JSON.parse(fs.readFileSync(path.join(dir,file),'utf8'));
  const page = {...fixture.page,items:fixture.items};
  const oldOutput = baseline.parseFramingPlan(page);
  const oldDebug = baselineAudit.parseFramingPlan(page);
  const newOutput = now.parseFramingPlan(page);
  const newDebug = nowAudit.parseFramingPlan(page);
  assert.equal(JSON.stringify(oldOutput),JSON.stringify(oldDebug));
  assert.equal(JSON.stringify(newOutput),JSON.stringify(newDebug));
  return {file,before:oldOutput,after:newOutput,before_measurements:baselineAudit.audit(oldDebug),after_measurements:nowAudit.audit(newDebug)};
});
function margin(key) {
  const rows = pages.flatMap(p=>p[key].map(r=>({page:p.file,...r})));
  const max = rows.reduce((a,b)=>a.accepted.distance_pt>=b.accepted.distance_pt?a:b);
  const min = rows.filter(r=>r.competitor).reduce((a,b)=>a.competitor.distance_pt<=b.competitor.distance_pt?a:b);
  const unconfirmed = rows.filter(r=>!r.totalConfirmed&&r.competitor).reduce((a,b)=>a.competitor.distance_pt<=b.competitor.distance_pt?a:b);
  return {page_count:pages.length,span_count:rows.length,A:max.accepted.distance_pt,B:min.competitor.distance_pt,holds:max.accepted.distance_pt<=15&&15<min.competitor.distance_pt,accepted_max:max,competing_min:min,unconfirmed_min:unconfirmed};
}
const census = pages.map(p=>{
  const oldKeys = p.before.grids.map(g=>JSON.stringify(g));
  const newKeys = p.after.grids.map(g=>JSON.stringify(g));
  return {page:p.file,before_grids:oldKeys.length,after_grids:newKeys.length,unchanged:oldKeys.filter(k=>newKeys.includes(k)).length,removed:p.before.grids.filter((g,i)=>!newKeys.includes(oldKeys[i])),added:p.after.grids.filter((g,i)=>!oldKeys.includes(newKeys[i])),before_blocks:p.before.blocks.map(b=>b.placements.length),after_blocks:p.after.blocks.map(b=>b.placements.length),blocks_byte_json_equal:JSON.stringify(p.before.blocks)===JSON.stringify(p.after.blocks)};
});
save('pages',pages);
save('measurements',{base,parser_sha256_before:sha(currentBytes),parser_sha256_after:sha(fs.readFileSync(parserPath)),historical:margin('before_measurements'),current:margin('after_measurements'),census});
console.log(JSON.stringify({historical:margin('before_measurements'),current:margin('after_measurements'),changed:census.filter(p=>p.removed.length||p.added.length),all_blocks_equal:census.every(p=>p.blocks_byte_json_equal)},null,2));
